import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8

__global__ void sgemm_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int N) {
    __shared__ float As[BM][BK];
    __shared__ float Bs[BK][BN];

    const int blockRow = blockIdx.y;
    const int blockCol = blockIdx.x;

    const int threadsPerRow = BN / TN; // 16
    const int threadRow = threadIdx.x / threadsPerRow; // 0..(BM/TM -1)
    const int threadCol = threadIdx.x % threadsPerRow;  // 0..(BN/TN -1)

    const int numThreads = (BM / TM) * (BN / TN); // 256

    const int rowStart = blockRow * BM;
    const int colStart = blockCol * BN;

    float threadResults[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            threadResults[i][j] = 0.0f;
        }
    }

    const int tid = threadIdx.x;

    for (int k0 = 0; k0 < N; k0 += BK) {
        // Load A tile: BM*BK elements
        for (int idx = tid; idx < BM * BK; idx += numThreads) {
            int r = idx / BK;
            int c = idx % BK;
            int globalRow = rowStart + r;
            int globalCol = k0 + c;
            As[r][c] = (globalRow < N && globalCol < N) ? A[(size_t)globalRow * N + globalCol] : 0.0f;
        }

        // Load B tile: BK*BN elements
        for (int idx = tid; idx < BK * BN; idx += numThreads) {
            int r = idx / BN;
            int c = idx % BN;
            int globalRow = k0 + r;
            int globalCol = colStart + c;
            Bs[r][c] = (globalRow < N && globalCol < N) ? B[(size_t)globalRow * N + globalCol] : 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BK; kk++) {
            float regA[TM];
            float regB[TN];
            #pragma unroll
            for (int i = 0; i < TM; i++) {
                regA[i] = As[threadRow * TM + i][kk];
            }
            #pragma unroll
            for (int j = 0; j < TN; j++) {
                regB[j] = Bs[kk][threadCol * TN + j];
            }
            #pragma unroll
            for (int i = 0; i < TM; i++) {
                #pragma unroll
                for (int j = 0; j < TN; j++) {
                    threadResults[i][j] += regA[i] * regB[j];
                }
            }
        }

        __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < TM; i++) {
        #pragma unroll
        for (int j = 0; j < TN; j++) {
            int globalRow = rowStart + threadRow * TM + i;
            int globalCol = colStart + threadCol * TN + j;
            if (globalRow < N && globalCol < N) {
                C[(size_t)globalRow * N + globalCol] = threadResults[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");

    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    TORCH_CHECK(A.size(1) == N, "A must be square");
    TORCH_CHECK(B.size(0) == N && B.size(1) == N, "B must be square with same N as A");

    auto C = torch::empty({N, N}, A.options());

    dim3 blockDim((BM / TM) * (BN / TN), 1, 1);
    dim3 gridDim((N + BN - 1) / BN, (N + BM - 1) / BM, 1);

    sgemm_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a single square matrix multiplication (C = A * B)
    using a custom tiled CUDA kernel with shared memory and register blocking.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().float()
        B = B.cuda().float()
        return self.matmul.matmul_cuda(A, B)


N = 2048 * 2


def get_inputs():
    A = torch.rand(N, N)
    B = torch.rand(N, N)
    return [A, B]


def get_init_inputs():
    return []

